using System.Collections.Generic;
using System.IO;
using Newtonsoft.Json.Linq;

namespace CardSurvivalArchipelago
{
    /// <summary>
    /// The item and location ids, read from registry.json (generated by tools/build_registry.py
    /// and installed next to the plugin). The APWorld uses the very same file, so both sides
    /// always agree on what an id means.
    /// </summary>
    internal static class Registry
    {
        public sealed class Entry
        {
            public long Id;
            public string Name;
            public string Key;        // the game's object name, e.g. "Bp_Kiln"
            public string CardId;     // the game's UniqueID of the card
            public string Kind;       // item kind: "blueprint" or "filler"
        }

        public static int Version { get; private set; }
        public static string Error { get; private set; }

        public static readonly Dictionary<long, Entry> Items = new Dictionary<long, Entry>();
        public static readonly Dictionary<long, Entry> Locations = new Dictionary<long, Entry>();
        /// <summary>Blueprint card UniqueID -> its research location.</summary>
        public static readonly Dictionary<string, Entry> ResearchByCard = new Dictionary<string, Entry>();
        /// <summary>Blueprint card UniqueID -> the item that unlocks its recipe.</summary>
        public static readonly Dictionary<string, Entry> BlueprintItemByCard = new Dictionary<string, Entry>();
        /// <summary>Filler item id -> list of (card UniqueID, count) it hands out.</summary>
        public static readonly Dictionary<long, List<KeyValuePair<string, int>>> FillerContents =
            new Dictionary<long, List<KeyValuePair<string, int>>>();

        public static bool Load(string folder)
        {
            string path = Path.Combine(folder, "registry.json");
            if (!File.Exists(path))
            {
                Error = "registry.json is missing next to the plugin.";
                return false;
            }
            JObject data = JObject.Parse(File.ReadAllText(path));
            Version = (int)data["registry_version"];
            foreach (JObject raw in data["items"])
            {
                var entry = new Entry
                {
                    Id = (long)raw["ap_id"], Name = (string)raw["name"], Key = (string)raw["key"],
                    CardId = (string)raw["unique_id"], Kind = (string)raw["kind"] ?? "blueprint",
                };
                Items[entry.Id] = entry;
                if (entry.Kind == "blueprint" && entry.CardId != null)
                {
                    BlueprintItemByCard[entry.CardId] = entry;
                }
                JArray contents = raw["contents"] as JArray;
                if (contents != null)
                {
                    var list = new List<KeyValuePair<string, int>>();
                    foreach (JObject card in contents)
                    {
                        list.Add(new KeyValuePair<string, int>((string)card["unique_id"], (int)card["count"]));
                    }
                    FillerContents[entry.Id] = list;
                }
            }
            foreach (JObject raw in data["locations"])
            {
                var entry = new Entry
                {
                    Id = (long)raw["ap_id"], Name = (string)raw["name"], Key = (string)raw["key"],
                    CardId = (string)raw["unique_id"],
                };
                Locations[entry.Id] = entry;
                ResearchByCard[entry.CardId] = entry;
            }
            Error = null;
            return true;
        }
    }
}
